PTX_SOURCE = r'''
.version 7.1
.target sm_80
.address_size 64

.visible .entry layernorm_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 N,
    .param .f32 eps
)
{
    .reg .pred   %p<2>;
    .reg .b32    %r<20>;
    .reg .b64    %rd<10>;
    .reg .f32    %f<20>;

    // Load kernel parameters
    ld.param.u64    %rd1, [input_ptr];
    ld.param.u64    %rd2, [output_ptr];
    ld.param.u32    %r1, [N];
    ld.param.f32    %f1, [eps];

    // batch index = blockIdx.x
    mov.u32 %r2, %ctaid.x;
    // thread index within block
    mov.u32 %r3, %tid.x;

    // Compute per‑batch base pointers (each element = 2 bytes)
    mul.wide.u32 %rd3, %r2, %r1;          // batch * N (elements)
    mul.wide.u32 %rd4, %rd3, 2;          // *2 (bytes)
    add.u64 %rd5, %rd1, %rd4;            // input base
    add.u64 %rd6, %rd2, %rd4;            // output base

    // -------------------------------------------------
    // First pass: compute sum and sum of squares
    // -------------------------------------------------
    mov.f32 %f2, 0.0;        // sum
    mov.f32 %f3, 0.0;        // sumsq

    // i = threadIdx.x; i < N; i += blockDim.x
    mov.u32 %r4, %r3;
sum_loop:
    setp.ge.u32 %p1, %r4, %r1;
    @%p1 bra sum_done;

    // address = base + i*2
    mul.wide.u32 %rd7, %r4, 2;
    add.u64 %rd8, %rd5, %rd7;
    ld.global.u16 %r5, [%rd8];          // load fp16 as u16
    cvt.f32.f16 %f4, %r5;               // to fp32

    add.f32 %f2, %f2, %f4;              // sum += val
    mul.f32 %f5, %f4, %f4;
    add.f32 %f3, %f3, %f5;              // sumsq += val*val

    add.u32 %r4, %r4, %ntid.x;          // stride
    bra sum_loop;
sum_done:

    // -------------------------------------------------
    // Block‑level reduction (tree reduction)
    // -------------------------------------------------
    .shared .align 4 .f32 s_sum[256];
    .shared .align 4 .f32 s_sumsq[256];
    .shared .align 4 .f32 s_mean;
    .shared .align 4 .f32 s_inv_std;

    st.shared.f32 [s_sum+%r3*4], %f2;
    st.shared.f32 [s_sumsq+%r3*4], %f3;
    bar.sync 0;

    // reduction: stride = blockDim.x/2 ... 1
    mov.u32 %r6, %ntid.x;
    shr.u32 %r6, %r6, 1;
reduce_loop:
    setp.eq.u32 %p1, %r6, 0;
    @%p1 bra reduce_done;

    setp.lt.u32 %p1, %r3, %r6;
    @%p1 {
        ld.shared.f32 %f6, [s_sum+%r3*4];
        ld.shared.f32 %f7, [s_sum+(%r3+%r6)*4];
        add.f32 %f6, %f6, %f7;
        st.shared.f32 [s_sum+%r3*4], %f6;

        ld.shared.f32 %f8, [s_sumsq+%r3*4];
        ld.shared.f32 %f9, [s_sumsq+(%r3+%r6)*4];
        add.f32 %f8, %f8, %f9;
        st.shared.f32 [s_sumsq+%r3*4], %f8;
    }
    bar.sync 0;
    shr.u32 %r6, %r6, 1;
    bra reduce_loop;
reduce_done:

    // -------------------------------------------------
    // Thread 0 computes mean & inverse std
    // -------------------------------------------------
    setp.eq.u32 %p1, %r3, 0;
    @%p1 {
        ld.shared.f32 %f10, [s_sum];
        ld.shared.f32 %f11, [s_sumsq];
        cvt.f32.u32 %f12, %r1;               // N as float
        div.f32 %f13, %f10, %f12;            // mean
        div.f32 %f14, %f11, %f12;            // mean of squares
        mul.f32 %f15, %f13, %f13;            // mean^2
        sub.f32 %f16, %f14, %f15;            // variance
        add.f32 %f16, %f16, %f1;             // + eps
        rsqrt.approx.f32 %f17, %f16;         // 1/sqrt(var+eps)
        st.shared.f32 [s_mean], %f13;
        st.shared.f32 [s_inv_std], %f17;
    }
    bar.sync 0;

    // Broadcast mean & inv_std to all threads
    ld.shared.f32 %f18, [s_mean];
    ld.shared.f32 %f19, [s_inv_std];

    // -------------------------------------------------
    // Second pass: normalize and write output
    // -------------------------------------------------
    mov.u32 %r4, %r3;
norm_loop:
    setp.ge.u32 %p1, %r4, %r1;
    @%p1 bra norm_done;

    mul.wide.u32 %rd7, %r4, 2;
    add.u64 %rd8, %rd5, %rd7;               // input address
    ld.global.u16 %r5, [%rd8];
    cvt.f32.f16 %f20, %r5;

    sub.f32 %f20, %f20, %f18;               // (x - mean)
    mul.f32 %f20, %f20, %f19;               // * inv_std

    cvt.f16.f32 %r6, %f20;                  // back to fp16
    add.u64 %rd9, %rd6, %rd7;               // output address
    st.global.u16 [%rd9], %r6;

    add.u32 %r4, %r4, %ntid.x;
    bra norm_loop;
norm_done:
    ret;
}
'''
# ----------------------------------------------------------------------
# Python wrapper that loads the PTX and launches the kernel
# ----------------------------------------------------------------------
import torch

class ModelNew:
    def __init__(self, normalized_shape):
        # normalized_shape = (features, dim1, dim2)
        self.features, self.dim1, self.dim2 = normalized_shape
        self.N = self.features * self.dim1 * self.dim2
        self.eps = 1e-5
        # Load PTX module via the harness
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        assert x.dtype == torch.float16, "Input must be fp16"
        out = torch.empty_like(x)
        batch = x.shape[0]
        grid = (batch,)               # one block per batch element
        block = (256,)                # 256 threads per block
        args = [x.data_ptr(), out.data_ptr(), self.N, self.eps]
        ptx_launch(self.module, "layernorm_kernel", grid, block, args)
        return out
